import struct

def _der_len(length: int) -> bytes:
    """Encode DER length."""
    if length < 0x80:
        return bytes([length])
    # long form
    len_bytes = length.to_bytes((length.bit_length() + 7) // 8, "big")
    return bytes([0x80 | len(len_bytes)]) + len_bytes


def _der_tag(tag: int, constructed: bool = False, cls: int = 0) -> bytes:
    """Encode a DER tag byte."""
    b = (cls << 6) | (0x20 if constructed else 0) | tag
    return bytes([b])


def _der_encode(tag: int, value: bytes, constructed: bool = False, cls: int = 0) -> bytes:
    """Generic DER encoder."""
    return _der_tag(tag, constructed, cls) + _der_len(len(value)) + value

